Item.method_code:
if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefReloadEntryGet|" + aml);
}
var selected = this.node;
selected.SelectSingleNode("name").InnerText = "Captured value";
this.loadAML("<AML><!--Entry marker--><Item type='RefPlain' action='add'><name>Current document</name></Item></AML>");
var root = this.dom.DocumentElement;
var current = this.node;
var name = current.SelectSingleNode("name");
var text = name.FirstChild;
var output = new System.Xml.XmlDocument();
eventData.BaseGetItem(output);
if (selected.ParentNode != null || selected.SelectSingleNode("name").InnerText != "Captured value")
{
    throw new Exception("BaseGet lost its earlier captured request");
}
if (!Object.ReferenceEquals(root, this.dom.DocumentElement)
    || !Object.ReferenceEquals(current, root.SelectSingleNode("Item"))
    || !Object.ReferenceEquals(text, name.FirstChild)
    || name.InnerText != "Changed current document")
{
    throw new Exception("BaseGet replaced current-document views instead of updating them");
}
var result = this.getInnovator().newItem();
result.loadAML(output.OuterXml);
return result;

if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefInspectEntryGet|" + aml);
}
if (this.getType() != "RefPlain" || this.getProperty("name") != "Current document")
{
    throw new Exception("The hook did not receive the current document");
}
this.setProperty("name", "Changed current document");
return this;
